INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2501, 'Exodus 36:9', 'Exodus', 36, 9, '&nbsp;ټولې پړدې په يو ناپ وې، هره يوه څوارلس ګزه اوږده او دوه ګزه پلنه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2502, 'Exodus 36:10', 'Exodus', 36, 10, '&nbsp;هغوئ پينځۀ پړدې يو ځائ وګنډلې او هغه نورې پينځۀ يې هم يو ځائ وګنډلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2503, 'Exodus 36:11', 'Exodus', 36, 11, '&nbsp;هغوئ په هره جوړه کښې د پړدې په بهرنۍ غاړه د آسمانى رنګ د کپړې کَړۍ جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2504, 'Exodus 36:12', 'Exodus', 36, 12, '&nbsp;هغوئ د وړومبۍ جوړې په وړومبۍ پړده پنځوس کَړۍ او پنځوس کَړۍ د دوېمې جوړې په آخرى پړده جوړې کړې چې دا کَړۍ يو بل ته مخامخ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2505, 'Exodus 36:13', 'Exodus', 36, 13, '&nbsp;پنځوس د سرو زرو کُنډې يې جوړې کړې او هغه پړدې يې د يوې بلې سره مِلاو کړې نو داسې ټوله مقدسه خېمه يو ځائ شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2506, 'Exodus 36:14', 'Exodus', 36, 14, '&nbsp;بيا هغوئ د چېلو د وړۍ نه جوړې شوې يوولس پړدې واخستلې او د خېمې پټولو دپاره يې يوه پړده ترې نه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2507, 'Exodus 36:15', 'Exodus', 36, 15, '&nbsp;هغوئ دا ټولې په يو ناپ جوړې کړې چې پينځلس ګزه اوږدې او دوه ګزه پلنې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2508, 'Exodus 36:16', 'Exodus', 36, 16, '&nbsp;هغوئ پينځۀ پړدې يو ځائ وګنډلې او هغه نورې شپږ يې هم يو ځائ وګنډلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2509, 'Exodus 36:17', 'Exodus', 36, 17, '&nbsp;د يوې جوړې د آخرى پړدې په غاړه يې پنځوس کَړۍ جوړې کړې او د هغه بلې جوړې په غاړه يې هم پنځوس کَړۍ جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2510, 'Exodus 36:18', 'Exodus', 36, 18, '&nbsp;هغوئ د زېړو پنځوس کُنډې جوړې کړې او هغه يې په کړو کښې واچولې چې هغه دوه جوړې يې سره مِلاو کړې نو داسې خېمه وتړلے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2511, 'Exodus 36:19', 'Exodus', 36, 19, '&nbsp;هغوئ دوه نورې پړدې هم جوړې کړې، يوه پړده يې د ګډو د څرمنې نه چې سور رنګ ورکړے شوے وو او بله يې د ښې څرمنې نه جوړه کړه، چې د پاس نه پرې خېمه پټه کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2512, 'Exodus 36:20', 'Exodus', 36, 20, '&nbsp;هغوئ د خېمې د ودرولو دپاره د کيکر د لرګى چوکاټونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2513, 'Exodus 36:21', 'Exodus', 36, 21, '&nbsp;هر يو چوکاټ پينځلس فټه اوږد وو او اوويشت اِنچې پلن وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2514, 'Exodus 36:22', 'Exodus', 36, 22, '&nbsp;سره د دوه يو شان تختو، چې دا چوکاټونه په خپلو کښې ونښلوى. د ټولو چوکاټونو دا تختې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2515, 'Exodus 36:23', 'Exodus', 36, 23, '&nbsp;هغوئ د خېمې جنوبى طرف دپاره شل چوکاټونه جوړ کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2516, 'Exodus 36:24', 'Exodus', 36, 24, '&nbsp;او څلوېښت د سپينو زرو پښې چې ورلاندې شى، د هر يو چوکاټ لاندې دوه دوه پښې چې هغه دوه وړاندينۍ حِصې يې نيولې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2517, 'Exodus 36:25', 'Exodus', 36, 25, '&nbsp;هغوئ د خېمې شمالى طرف دپاره هم شل چوکاټونه جوړ کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2518, 'Exodus 36:26', 'Exodus', 36, 26, '&nbsp;او څلوېښت د سپينو زرو پښې، چې د هر يو چوکاټ لاندې دوه دوه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2519, 'Exodus 36:27', 'Exodus', 36, 27, '&nbsp;د نمرپرېواتۀ په طرف خېمې شا ته هغوئ شپږ چوکاټونه جوړ کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2520, 'Exodus 36:28', 'Exodus', 36, 28, '&nbsp;او دوه چوکاټونه يې د خېمې د ګوټونو دپاره هم جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2521, 'Exodus 36:29', 'Exodus', 36, 29, '&nbsp;د ګوټونو دا چوکاټونه په بېخ کښې مِلاو وُو او د لاندې نه واخله تر سر پورې خپلو کښې انښتى وُو. دا دوه چوکاټونه هم د ګوټونو د دوه چوکاټونو په شان جوړ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2522, 'Exodus 36:30', 'Exodus', 36, 30, '&nbsp;نو اتۀ چوکاټونه او شپاړس د سپينو زرو پښې وې، چې د هر چوکاټ لاندې دوه دوه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2523, 'Exodus 36:31', 'Exodus', 36, 31, '&nbsp;هغوئ د کيکر د لرګى نه پينځلس لاړى جوړ کړل، پينځۀ د خېمې د هغو چوکاټونو دپاره چې په يو طرف باندې وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2524, 'Exodus 36:32', 'Exodus', 36, 32, '&nbsp;پينځۀ د هغو چوکاټونو دپاره چې په بل طرف باندې وُو او پينځۀ د هغه چوکاټونو دپاره چې نمرخاتۀ په طرف شا ته په آخر سر کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2525, 'Exodus 36:33', 'Exodus', 36, 33, '&nbsp;تير د يو سر نه تر بل سره پورې پوره رسېدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2526, 'Exodus 36:34', 'Exodus', 36, 34, '&nbsp;هغوئ په چوکاټونو د سرو زرو پترى خېژولى وُو او د سرو زرو کَړۍ يې ورله جوړې کړې وې چې لاړى ونيسى، په لاړو باندې هم د سرو زرو پترى خېژولے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2527, 'Exodus 36:35', 'Exodus', 36, 35, '&nbsp;هغوئ د کتان نه يوه پړده جوړه کړه چې د آسمانى، کاسنى او د سور رنګ وړۍ نه تياره شوې وه او په دې باندې يې په ګُلکارۍ کښې د وزرو والا مخلوق جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2528, 'Exodus 36:36', 'Exodus', 36, 36, '&nbsp;هغوئ د کيکر د لرګى نه څلور ستنې جوړې کړې چې پړده په کښې په کُنډو کښې راځوړنده شى، په دې ستنو باندې د سرو زرو پترى خېژولے شوى وُو. بيا هغوئ څلور د سپينو زرو پښې ورله جوړې کړې چې ستنې ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2529, 'Exodus 36:37', 'Exodus', 36, 37, '&nbsp;هغوئ د خېمې د ننوتلو دروازې دپاره د کتان نه يوه پړده جوړه کړه چې د آسمانى، کاسنى او د سور رنګ وړۍ نه تياره شوې وه او چې په ګُلکارۍ باندې ښائسته کړے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2530, 'Exodus 36:38', 'Exodus', 36, 38, '&nbsp;د دې پړدې دپاره هغوئ پينځۀ ستنې جوړې کړې چې کُنډې په کښې لګېدلې وې، د دې په سرونو او سيخونو د سرو زرو پترى خېژولے شوى وُو او د دې ستنو دپاره يې پينځۀ د زېړو پښې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2531, 'Exodus 37:1', 'Exodus', 37, 1, '&nbsp;بضلى‌اېل د کيکر د لرګى نه د لوظ صندوق جوړ کړو، چې پينځۀ څلوېښت اِنچۍ اوږد وو او اوويشت اِنچۍ پلن او اوويشت اِنچۍ لوړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2532, 'Exodus 37:2', 'Exodus', 37, 2, '&nbsp;بهر او دننه يې د سوچه سرو زرو پترى پرې وخېژول او ګېرچاپېره يې ترې نه د سرو زرو غاړه شان تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2533, 'Exodus 37:3', 'Exodus', 37, 3, '&nbsp;د وړولو دپاره هغۀ ورله د سرو زرو څلور کَړۍ جوړې کړې او دا يې ورله په څلور پښو پورې ولګولې، چې دوه کَړۍ په يو خوا وې او دوه يې بل خوا وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2534, 'Exodus 37:4', 'Exodus', 37, 4, '&nbsp;د وړلو دپاره يې ورله د کيکر د لرګى بازوګان جوړ کړل او د سرو زرو پترى يې ورباندې وخېژول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2535, 'Exodus 37:5', 'Exodus', 37, 5, '&nbsp;او دا يې د لوظ د صندوق په کړو کښې دواړو طرفونو ته وردننه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2536, 'Exodus 37:6', 'Exodus', 37, 6, '&nbsp;هغۀ ورله د سوچه سرو زرو يو د کفارې تخت جوړ کړو، چې پينځۀ څلوېښت اِنچۍ اوږد وو او اوويشت اِنچۍ پلن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2537, 'Exodus 37:7', 'Exodus', 37, 7, '&nbsp;د ټکېدلے شوو سرو زرو نه يې دوه د وزرو والا مخلوق جوړ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2538, 'Exodus 37:8', 'Exodus', 37, 8, '&nbsp;يو يې په يو سر او بل يې په بل سر کښې پرې جوړ کړو. هغۀ دا داسې جوړ کړل چې دواړه د صندوق د کفارې د سر سره يو ځائ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2539, 'Exodus 37:9', 'Exodus', 37, 9, '&nbsp;د وزرو والا مخلوق د صندوق د کفارې په تخت باندې يو بل ته مخامخ وُو او خورو وزرو يې د صندوق سر پټ کړے وو او مخونه يې لاندې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2540, 'Exodus 37:10', 'Exodus', 37, 10, '&nbsp;د کيکر د لرګى نه هغۀ يو مېز جوړ کړو، چې شپږ دېرش اِنچۍ اوږد وو، اتلس اِنچۍ پلن او اوويشت اِنچۍ لوړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2541, 'Exodus 37:11', 'Exodus', 37, 11, '&nbsp;په دې يې د سوچه سرو زرو پترى وخېژول او ګېرچاپېره يې ورله د سرو زرو غاړه تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2542, 'Exodus 37:12', 'Exodus', 37, 12, '&nbsp;ګېرچاپېره يې درې اِنچۍ پلنه يوه ژۍ ورله جوړه کړه او د ژۍ نه ګېرچاپېره يې د سرو زرو غاړه تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2543, 'Exodus 37:13', 'Exodus', 37, 13, '&nbsp;د وړلو دپاره يې ورله د سرو زرو څلور ګول کَړۍ جوړې کړې او دا يې ورله په څلورو ګوټونو کښې ولګولې، چرته چې پښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2544, 'Exodus 37:14', 'Exodus', 37, 14, '&nbsp;هغۀ دا کَړۍ د ژۍ سره نزدې ولګولې چې هغه بازوګان ونيسى چې د کومو په ذريعه دا مېز وړلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2545, 'Exodus 37:15', 'Exodus', 37, 15, '&nbsp;دا بازوګان يې د کيکر د لرګى نه جوړ کړل او په دې باندې يې د سرو زرو پترى وخېژول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2546, 'Exodus 37:16', 'Exodus', 37, 16, '&nbsp;هغۀ د مېز دپاره د سوچه سرو زرو نه دا لوښى جوړ کړل، جامونه، کاسې، رکېبۍ او د څښلو نذرانو تويَولو دپاره منګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2547, 'Exodus 37:17', 'Exodus', 37, 17, '&nbsp;د سوچه سرو زرو نه هغۀ ډيوټ جوړ کړو. د دې بېخ او ډنډا يې د ټکېدلے شوو سرو زرو نه جوړه کړه، د دې د ښۀ ښکارېدلو ګلونه، سره د غوټو او پاڼو، چې د دې سره يو ځائ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2548, 'Exodus 37:18', 'Exodus', 37, 18, '&nbsp;د دې د اړخونو نه شپږ څانګې وتلې وې، چې درې په يو طرف وې او درې په بل طرف وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2549, 'Exodus 37:19', 'Exodus', 37, 19, '&nbsp;د دې شپږ واړو څانګو درې درې د ښۀ ښکارېدو ګلونه وُو دا سره د غوټو او پاڼو د بادام د ګلونو په شان جوړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2550, 'Exodus 37:20', 'Exodus', 37, 20, '&nbsp;د ډيوټ د ډنډې د ښۀ ښکارېدو دپاره څلور ګلونه وُو، دا سره د غوټو او پاڼو د بادام د ګلونو په شان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2551, 'Exodus 37:21', 'Exodus', 37, 21, '&nbsp;د څانګو د دې درېو جوړو د هرې يوې لاندې يوه غوټۍ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2552, 'Exodus 37:22', 'Exodus', 37, 22, '&nbsp;دا غوټۍ، څانګې او ډيوټ د ټکېدلے شوو سوچه سرو زرو د يوې ټُکړې نه جوړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2553, 'Exodus 37:23', 'Exodus', 37, 23, '&nbsp;د ډيوټ دپاره هغۀ اووۀ ډيوې جوړې کړې او هغۀ ورله د سوچه سرو زرو نه ايره پاکوونکې چمټې او مجمعې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2554, 'Exodus 37:24', 'Exodus', 37, 24, '&nbsp;هغۀ پينځۀ دېرش کلو سوچه سرۀ زر په ډيوټ او د دې ټول سامان جوړولو کښې استعمال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2555, 'Exodus 37:25', 'Exodus', 37, 25, '&nbsp;د خوشبويۍ سوزولو دپاره هغۀ د کيکر د لرګى نه يوه قربان‌ګاه جوړه کړه. دا څلور‌ګوټه وه، اتلس اِنچۍ اوږده، اتلس اِنچۍ پلنه او يو ګز اوچته وه. څلور د ښکرو په شان ګوټونه يې ورله جوړ کړى وُو چې د قربان‌ګاه سره يو ځائ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2556, 'Exodus 37:26', 'Exodus', 37, 26, '&nbsp;هغۀ د هغې په چت، څلورو طرفونو او د هغې د ښکرو په شان څيزونو باندې د سوچه سرو زرو پترى وخېژول او ګېرچاپېره يې ترې نه د سرو زرو غاړه شان تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2557, 'Exodus 37:27', 'Exodus', 37, 27, '&nbsp;د هغې دپاره يې دوه د سرو زرو کَړۍ جوړې کړې او لاندې يې دواړو طرفونو ته د غاړې سره وتړلې چې هغه بازوګان ونيسى چې د کومو په ذريعه دا وړلے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2558, 'Exodus 37:28', 'Exodus', 37, 28, '&nbsp;هغۀ دا بازوګان د کيکر د لرګى نه جوړ کړل او په دې يې د سرو زرو پترى وخېژول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2559, 'Exodus 37:29', 'Exodus', 37, 29, '&nbsp;هغۀ د غوړولو مقدس تېل او سوچه خوشبوئى هم جوړه کړه، دا يې داسې مِلاو کړل لکه چې د عطرو والا دا کار کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2560, 'Exodus 38:1', 'Exodus', 38, 1, '&nbsp;د سوزېدونکې نذرانې دپاره، د کيکر د لرګى نه بضلى‌اېل يوه قربان‌ګاه جوړه کړه. هغه څلور‌ګوټه وه، چې اووۀ نيم فټه اوږده وه، اووۀ نيم فټه پلنه او څلور نيم فټه لوړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2561, 'Exodus 38:2', 'Exodus', 38, 2, '&nbsp;هغۀ د څلورو ګوټونو دپاره د ښکرونو په شان څيزونه جوړ کړل چې د قربان‌ګاه سره يې يو ځائ کړل. هغۀ په دې هر څۀ باندې د زېړو پترى خېژولى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2562, 'Exodus 38:3', 'Exodus', 38, 3, '&nbsp;هغۀ د قربان‌ګاه دپاره دا ټول سامان هم جوړ کړو، د ايرو د لرې کولو دپاره لوښى، بېلچې، جامونه، درې غاښى او د ګرمې ايرې لرې کولو دپاره لوښى. دا ټول سامان د زېړو نه جوړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2563, 'Exodus 38:4', 'Exodus', 38, 4, '&nbsp;هغۀ د زېړو يوه جالۍ جوړه کړه او دا يې د قربان‌ګاه د ژۍ لاندې کېښوده، چې د قربان‌ګاه مينځ ته رسېدلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2564, 'Exodus 38:5', 'Exodus', 38, 5, '&nbsp;هغۀ څلور کَړۍ جوړې کړې او په څلورو ګوټونو يې ورله ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2565, 'Exodus 38:6', 'Exodus', 38, 6, '&nbsp;هغۀ د وړولو دپاره د کيکر د لرګى نه ورله څلور بازوګان جوړ کړل او د زېړو پترى يې ورباندې وخېژول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2566, 'Exodus 38:7', 'Exodus', 38, 7, '&nbsp;او د قربان‌ګاه دواړو طرفونو ته چې کومې کَړۍ وې په هغې کښې يې ولګولې. قربان‌ګاه د لرګى تختو نه جوړه وه او د مينځ نه تشه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2567, 'Exodus 38:8', 'Exodus', 38, 8, '&nbsp;بضلى‌اېل ښانک او د دې بېخ د زېړو نه جوړ کړل. د دې زېړ د هغې ښځو د ائينو نه مِلاو شوى وُو کومو چې د مالِک خُدائ د حضور خېمې په دروازه کښې خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2568, 'Exodus 38:9', 'Exodus', 38, 9, '&nbsp;هغۀ د کتان د پړدو نه د مالِک خُدائ د حضور خېمې دپاره دربار جوړ کړو. د جنوب په طرف پړدې پنځوس ګزه اوږدې وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2569, 'Exodus 38:10', 'Exodus', 38, 10, '&nbsp;دا د زېړو شلو ستنو او د زېړو په شلو پښو کښې، د سپينو زرو کُنډو او د سپينو زرو سيخونو په ذريعه ټينګې کړے شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2570, 'Exodus 38:11', 'Exodus', 38, 11, '&nbsp;دربار د شمال په طرف هم دومره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2571, 'Exodus 38:12', 'Exodus', 38, 12, '&nbsp;د نمرپرېواتۀ په طرف هم پينځويشت ګزه اوږدې پړدې وې، سره د لسو ستنو او لسو پښو او د کُنډو او سيخونو چې د سپينو زرو نه جوړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2572, 'Exodus 38:13', 'Exodus', 38, 13, '&nbsp;نمرخاتۀ په طرف، چرته چې دروازه وه، هلته هم دربار پينځويشت ګزه اوږد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2573, 'Exodus 38:16', 'Exodus', 38, 16, '&nbsp;د دربار ګېرچاپېره ټولې پړدې د کتان نه جوړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2574, 'Exodus 38:17', 'Exodus', 38, 17, '&nbsp;د ستنو پښې د زېړو نه جوړې کړے شوې وې او د دې کُنډې، سيخونه او د ستنو دپاسه سرونه د سپينو زرو نه جوړ وُو. د دربار نه ګېرچاپېره ټولې ستنې د سپينو زرو سيخونو سره انښلولے شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2575, 'Exodus 38:18', 'Exodus', 38, 18, '&nbsp;د دربار د دروازې پړده د مهينې لټې نه جوړه وه چې د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه تياره شوې وه. او په ګُلکارۍ ښائسته کړے شوې وه. دا د دربار د پړدو په شان، لس ګزه اوږده او دوه نيم ګزه اوچته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2576, 'Exodus 38:19', 'Exodus', 38, 19, '&nbsp;دا د څلورو ستنو او د زېړو څلورو پښو په ذريعه ټينګه کړے شوې وه، کُنډې، د ستنو پاسنى سرونه او سيخونه يې د سپينو زرو نه جوړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2577, 'Exodus 38:20', 'Exodus', 38, 20, '&nbsp;د خېمې او د دربار دپاره ګېرچاپېره ټول موږى د زېړو نه جوړ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2578, 'Exodus 38:21', 'Exodus', 38, 21, '&nbsp;دا د هغه څيزونو تفصيل دے کوم چې د مالِک خُدائ د حضور په خېمه کښې استعمال شوى وُو، چرته چې د کاڼو هغه دوه تختې ساتلے شوې وې چې لس حُکمونه ورباندې ليکلے شوى وُو. د تفصيل د تيارولو حُکم موسىٰ ورکړے وو او د دې کار دپاره د ليويانو مشر اِتمر وو چې د هارون اِمام زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2579, 'Exodus 38:22', 'Exodus', 38, 22, '&nbsp;د يهوداه د قبيلې، بضلى‌اېل، چې د اورى زوئ او د حُور نمسے وو، هغه هر څۀ جوړ کړل چې مالِک خُدائ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2580, 'Exodus 38:23', 'Exodus', 38, 23, '&nbsp;د هغۀ مدد کوونکے، د دان د قبيلې اهلياب د اخيسمک زوئ وو، هغه زرګر وو، هغه ماهِر او د کتان او د آسمانى رنګ، کاسنى او د سور رنګ وړۍ جوړونکے هم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2581, 'Exodus 38:24', 'Exodus', 38, 24, '&nbsp;مقدسې خېمې دپاره مالِک خُدائ ته وقف شوى ټول سرۀ زر زر کلو وُو، چې د منلے شوى معيار په مطابق تَللے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2582, 'Exodus 38:25', 'Exodus', 38, 25, '&nbsp;د بنى اِسرائيلو د مردم‌شمارۍ په وخت چې کوم سپين زر راجمع شوى وُو، هغه درې زره څلور سوه او دېرش کلو وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2583, 'Exodus 38:26', 'Exodus', 38, 26, '&nbsp;کوم سړى چې په مردم‌شمارۍ کښې شامل شوى وُو هر يو کس د منلے شوى معيار په مطابق هغه مقرر شوے قيمت ورکړو. په مردم‌شمارۍ کښې شامل شوى سړى شپږ لاکه درې زره پينځۀ سوه پنځوس وُو چې د هغوئ عُمر شل کاله يا د دې نه زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2584, 'Exodus 38:27', 'Exodus', 38, 27, '&nbsp;درې زره او څلور سوه کلو سپين زر په کښې استعمال شوى وُو د مقدسې خېمې د سلو پښو او د پړدې دپاره، د هرې يوې پښې دپاره څلور دېرش کلو استعمال شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2585, 'Exodus 38:28', 'Exodus', 38, 28, '&nbsp;د پاتې دېرش کلو سپينو زرو نه بضلى‌اېل سيخونه، د ستنو دپاره کُنډې او د ستنو پاسنى سرونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2586, 'Exodus 38:29', 'Exodus', 38, 29, '&nbsp;کوم زېړ چې مالِک خُدائ ته وقف شوى وُو هغه دوه زره څلور سوه او پينځويشت کلو وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2587, 'Exodus 38:30', 'Exodus', 38, 30, '&nbsp;هغۀ د دې نه د مالِک خُدائ د حضور خېمې د دروازې دپاره پښې، د زېړو قربان‌ګاه سره د زېړو جالۍ او د قربان‌ګاه دپاره نور ټول سامان جوړ کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2588, 'Exodus 38:31', 'Exodus', 38, 31, '&nbsp;د دربار ګېرچاپېره او د دربار د دروازې دپاره پښې او د خېمې دپاره او ګېرچاپېره د دربار دپاره ټول موږى يې ترې نه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2589, 'Exodus 39:1', 'Exodus', 39, 1, '&nbsp;د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه هغوئ ښائسته لِباس جوړ کړو کوم به چې اِمامانو په مقدس ځائ کښې د خِدمت کولو په وخت اغوستلو. هغوئ د هارون دپاره د اِمامانو لِباس جوړ کړو، هم هغه شان چې څنګه مالِک خُدائ موسىٰ ته حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2590, 'Exodus 39:2', 'Exodus', 39, 2, '&nbsp;هغوئ د کتان، د آسمانى رنګ، کاسنى او د سور رنګ وړۍ، او د سرو زرو تار نه پېش بند جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2591, 'Exodus 39:3', 'Exodus', 39, 3, '&nbsp;هغوئ د سرو زرو پاڼې وټکولې او نرى نرى تارونه يې ترې نه جوړ کړل چې په کتان او د آسمانى رنګ، کاسنى او د سور رنګ په وړۍ جوړولو کښې ترې نه کار اخستلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2592, 'Exodus 39:4', 'Exodus', 39, 4, '&nbsp;هغوئ د پېش بند دپاره دواړو طرفو ته د ولى پټۍ لګولې وې، چې د دې په ذريعه تړلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2593, 'Exodus 39:5', 'Exodus', 39, 5, '&nbsp;يو ښۀ ګُلکارى شوے کمربند، چې هغه هم د هغه سامان نه جوړ وو، هغه د پېش بند سره انښلولے شوے وو او ورسره يو ځائ شوے وو، هم هغه شان لکه څنګه چې مالِک خُدائ موسىٰ ته حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2594, 'Exodus 39:6', 'Exodus', 39, 6, '&nbsp;هغوئ اونيکس کاڼى تيار کړل او په سرو زرو کښې يې ګېر کړل، په دې باندې د يعقوب د دولسو زامنو نومونه د يو ماهِر زرګر په ذريعه ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2595, 'Exodus 39:7', 'Exodus', 39, 7, '&nbsp;هغوئ دا د پېش بند د ولى په پټو باندې ولګول چې د بنى اِسرائيلو د دولسو قبيلو نمائندګى کوى، هم هغه شان لکه څنګه چې مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2596, 'Exodus 39:8', 'Exodus', 39, 8, '&nbsp;هغوئ هم د هغه کتان نه د سينې جېب جوړ کړو چې د کوم نه پېش بند جوړ وو او هم هغه شان ګُلکارى پرې شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2597, 'Exodus 39:9', 'Exodus', 39, 9, '&nbsp;دا څلور‌ګوټه او دوه غبرګه وو، نهۀ اِنچۍ اوږد او نهۀ اِنچۍ پلن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2598, 'Exodus 39:10', 'Exodus', 39, 10, '&nbsp;هغوئ په دې باندې څلور قطاره قيمتى کاڼى ولګول، په اول قطار کښې ياقوت، يو طوپاز او لعل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2599, 'Exodus 39:11', 'Exodus', 39, 11, '&nbsp;په دوېم قطار کښې، يو زمرد، يو نيلم او يوه هيره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2600, 'Exodus 39:12', 'Exodus', 39, 12, '&nbsp;په درېم قطار کښې، يو کائنائټ، يو عقيق او يو کټېله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');